#include <stdint.h>

/* Địa chỉ thanh ghi từ CMSIS-STM32F469XX-H */
#define PERIPH_BASE           (0x40000000UL)
#define AHB1PERIPH_BASE       (PERIPH_BASE + 0x00020000UL)

/* RCC: 0x40023800 */
#define RCC_BASE              (AHB1PERIPH_BASE + 0x3800UL)
#define RCC_AHB1ENR           (*(volatile uint32_t *)(RCC_BASE + 0x30UL))
#define RCC_AHB1ENR_GPIOGEN   (1UL << 6)

/* GPIOG: 0x40021800 */
#define GPIOG_BASE            (AHB1PERIPH_BASE + 0x1800UL)
#define GPIOG_MODER           (*(volatile uint32_t *)(GPIOG_BASE + 0x00UL))
#define GPIOG_ODR             (*(volatile uint32_t *)(GPIOG_BASE + 0x14UL))
#define GPIOG_BSRR            (*(volatile uint32_t *)(GPIOG_BASE + 0x18UL))

/* LED1 (Green) nối vào chân PG6 (tài liệu BSP-STM32469I-DISCO-H dòng 131, 145) */
#define LED1_PIN              (6U)

static void delay_cycles(volatile uint32_t count) {
    while (count--) {
        __asm__ volatile ("nop");
    }
}

int main(void) {
    /* 1. Bật clock cho cổng GPIOG */
    RCC_AHB1ENR |= RCC_AHB1ENR_GPIOGEN;

    /* 2. Cấu hình PG6 thành General Purpose Output mode (MODER[13:12] = 01b) */
    GPIOG_MODER &= ~(3UL << (LED1_PIN * 2));
    GPIOG_MODER |=  (1UL << (LED1_PIN * 2));

    /* 3. Vòng lặp chính: đảo trạng thái đèn LED1 với chu kỳ ~0.5s */
    while (1) {
        /* Bật LED1 */
        GPIOG_BSRR = (1UL << LED1_PIN);
        delay_cycles(1000000);

        /* Tắt LED1 */
        GPIOG_BSRR = (1UL << (LED1_PIN + 16));
        delay_cycles(1000000);
    }

    return 0;
}

